const input = $input.first().json.body || $input.first().json;

const outlineId = input.outline_id;
if (!outlineId) {
  throw new Error('Must provide outline_id');
}

const mode = input.mode || 'full';
const sectionNumbers = input.section_numbers || [];
const skipSections = input.skip_sections || [];

const defaultStyle = {
  tone: 'professional',
  reading_level: 'general',
  pov: 'second',
  use_analogies: true,
  use_examples: true,
  include_summaries: true,
  include_action_items: true
};
const style = { ...defaultStyle, ...(input.style || {}) };

return [{
  json: {
    outline_id: outlineId,
    mode: mode,
    section_numbers: mode === 'full' ? 'all' : sectionNumbers,
    skip_sections: skipSections,
    style: style,
    quality_threshold: input.quality_threshold || 70,
    callback_workflow: input.callback_workflow || null,
    session_id: `chapter_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    started_at: new Date().toISOString()
  }
}];

const config = $('Validate & Configure').first().json;
const outline = $input.first().json;

let sections = [];
try { sections = JSON.parse(outline.sections || '[]'); } catch(e) {}

let sectionsToWrite = [];
if (config.section_numbers === 'all') {
  sectionsToWrite = sections.filter(s => !config.skip_sections.includes(s.number));
} else {
  const nums = Array.isArray(config.section_numbers) ? config.section_numbers : [config.section_numbers];
  sectionsToWrite = sections.filter(s => nums.includes(s.number));
}

if (sectionsToWrite.length === 0) sectionsToWrite = sections;

const globalContext = {
  title: outline.title,
  subtitle: outline.subtitle,
  format: outline.format,
  total_sections: sections.length
};

return sectionsToWrite.map(section => ({
  json: {
    ...config,
    section: section,
    global_context: globalContext,
    outline_record_id: outline.outline_id
  }
}));

