parameters.jsCode:
const inputData = $('Prepare Sections').item.json;
const content = $input.item.json.message?.content || '';

const wordCount = content.split(/\s+/).filter(w => w.length > 0).length;
const targetWords = inputData.section.target_words || 1000;
const variance = Math.abs(wordCount - targetWords) / targetWords;

let score = 50;
score += (variance <= 0.15) ? 20 : Math.max(0, 20 - (variance * 100));
score += content.includes('## ') ? 10 : 0;
score += content.includes('### ') ? 10 : 0;
score = Math.min(100, Math.round(score));

const chapterId = `chapter_${inputData.session_id}_s${inputData.section.number}`;

// Build markdown file content with metadata header
let markdown = `# Chapter ${inputData.section.number}: ${inputData.section.title}\n\n`;
markdown += `**Book:** ${inputData.global_context.title}\n`;
markdown += `**Chapter ID:** ${chapterId}\n`;
markdown += `**Word Count:** ${wordCount}\n`;
markdown += `**Quality Score:** ${score}/100\n`;
markdown += `**Generated:** ${new Date().toISOString()}\n\n`;
markdown += `---\n\n`;
markdown += content;
markdown += `\n\n---\n\n*Generated by Production Line W9 Chapter Writer*\n`;

// Create safe filename
const safeTitle = inputData.section.title
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 30);
const timestamp = new Date().toISOString().split('T')[0];
const fileName = `chapter_${String(inputData.section.number).padStart(2, '0')}_${safeTitle}_${timestamp}.md`;
const filePath = `C:/dev/production_line/chapters/${fileName}`;

return [{
  json: {
    chapter_id: chapterId,
    outline_id: inputData.outline_record_id,
    section_number: inputData.section.number,
    title: inputData.section.title,
    type: inputData.section.type,
    content: content,
    word_count: wordCount,
    target_words: targetWords,
    quality_score: score,
    style: JSON.stringify(inputData.style),
    file_path: filePath,
    markdown_content: markdown,
    callback_workflow: inputData.callback_workflow,
    session_id: inputData.session_id,
    status: 'draft'
  }
}];

const data = $('Build Chapter Record').item.json;
const content = data.markdown_content;

const binaryData = Buffer.from(content, 'utf-8');

return [{
  json: {
    file_path: data.file_path,
    chapter_id: data.chapter_id
  },
  binary: {
    data: {
      data: binaryData.toString('base64'),
      mimeType: 'text/markdown',
      fileName: data.file_path.split('/').pop()
    }
  }
}];

const allContent = $input.first().json.data || [];
const config = $('Validate & Configure').first().json;

const totalWords = allContent.reduce((sum, c) => sum + (c.word_count || 0), 0);
const avgQuality = allContent.length > 0 
  ? Math.round(allContent.reduce((sum, c) => sum + (c.quality_score || 0), 0) / allContent.length) 
  : 0;

const completedAt = new Date().toISOString();
const durationMs = new Date(completedAt) - new Date(config.started_at);

return [{
  json: {
    success: true,
    mode: config.mode,
    outline_id: config.outline_id,
    sections_written: allContent.length,
    section_summary: allContent.map(c => ({
      section: c.section_number,
      title: c.title,
      words: c.word_count,
      quality: c.quality_score,
      file_path: c.file_path
    })),
    chapter_ids: allContent.map(c => c.chapter_id),
    file_paths: allContent.map(c => c.file_path),
    totals: { words: totalWords, avg_quality: avgQuality },
    storage: 'n8n_data_table + local_files',
    duration_seconds: Math.round(durationMs / 1000),
    ready_for_assembly: config.mode === 'full',
    callback_workflow: config.callback_workflow
  }
}];
